function exportInsights(){
  const records=insightRecords();
  const escape=pdlCsvCell;
  const rounded=value=>Number.isFinite(Number(value))?String(Number(Number(value).toFixed(2))):'';
  const percent=value=>Number.isFinite(Number(value))?Number(value).toFixed(1):'';
  const rows=[['Date','Project','Line item','Crew','Quantity','Unit','Labor hours','Quantity per hour','Efficiency vs estimate']];
  for(const row of records){
    const rate=Number(row.laborHours)>0?Number(row.quantity)/Number(row.laborHours):null;
    const efficiency=row.targetHoursPerUnit&&Number(row.laborHours)>0?Number(row.quantity)*Number(row.targetHoursPerUnit)/Number(row.laborHours)*100:null;
    rows.push([row.date,row.projectName,row.scope,row.crew,rounded(row.quantity),row.unit,rounded(row.laborHours),rounded(rate),percent(efficiency)]);
  }
  const blob=new Blob([rows.map(row=>row.map(escape).join(',')).join('\r\n')],{type:'text/csv'});
  const link=document.createElement('a');
  link.href=URL.createObjectURL(blob);
  link.download=`production-insights-${localDateIso()}.csv`;
  link.click();
  URL.revokeObjectURL(link.href);
  notify(`${records.length} production records exported`);
}
