function openProjectDailyReport(projectId,reportId){
  const dialog=$('#project-detail-modal');
  if(!dialog.open||Number(dialog.dataset.projectId)!==Number(projectId))return;
  // Use only the reports already supplied for this signed-in workspace. Never
  // let the renderer's first-report fallback substitute for the tapped daily.
  const report=reports.find(item=>item.id===reportId&&Number(projects[item.project]?.id)===Number(projectId));
  if(!report){notify('This daily report is no longer available. Reopen the project to refresh its reports.');return}
  const filter=$('#report-status-filter');
  if(filter&&filter.value!=='all'&&filter.value!==report.status)filter.value='all';
  reportReturnProjectId=projectId;$('#close-report-view').hidden=false;
  dialog.close();showPage('reports');renderReports(reportId);
  const detail=$('#report-detail');detail.setAttribute('tabindex','-1');detail.focus({preventScroll:true});
  // Rendering is synchronous. Scroll now so a queued callback cannot move the
  // viewport after the user has already navigated elsewhere.
  detail.scrollIntoView({behavior:'instant',block:'start'});
}
const openProjectEstimateView=openProject;
openProject=async function(id,view){
  await openProjectEstimateView(id,view);
  if(view&&!view.current())return;
  const project=projects.find(item=>item.id===id);
  if(currentRole!=='office'||!canViewCompanyPricing()||!project||!['tm','hybrid'].includes(project.contractType))return;
  try{
    const summary=await api(`/api/projects/${id}/tm-summary`);if(view&&!view.current())return;const label=project.contractType==='tm'?'Time & material':'Hybrid';
    const rows=summary.labor.length?summary.labor.map(row=>`<div class="tm-labor-row"><strong>${escapeHtml(row.classification)}</strong><span>${row.hours.toLocaleString()} hrs ${row.rate==null?'· rate needs review':`× $${row.rate.toLocaleString()}`}</span><strong>${row.amount==null?'Incomplete':`$${row.amount.toLocaleString()}`}</strong></div>`).join(''):'<div class="estimate-empty">Approved daily labor will appear here.</div>';
    $('#project-detail-content').insertAdjacentHTML('beforeend',`<section class="tm-summary"><div class="estimate-header"><div><h3>${label} summary</h3><small>Verified totals from approved daily reports only</small></div><span class="contract-type">${label}</span></div><div class="tm-summary-grid"><div><small>APPROVED DAILIES</small><strong>${summary.approvedDailies}</strong></div><div><small>LABOR HOURS</small><strong>${summary.laborHours.toLocaleString()}</strong></div><div><small>LABOR VALUE</small><strong>${summary.laborAmount==null?'Incomplete':`$${summary.laborAmount.toLocaleString()}`}</strong></div><div><small>MATERIAL / EQUIPMENT LOGS</small><strong>${summary.materialEntries} / ${summary.equipmentEntries}</strong></div></div><div class="tm-labor-row"><small>CLASSIFICATION</small><small>HOURS & RATE</small><small>AMOUNT</small></div>${rows}${summary.missingRateReports?.length?`<p>${summary.missingRateReports.length} approved daily rate${summary.missingRateReports.length===1?'':'s'} need historical review. Open the daily to record evidence; no total is guessed.</p>`:''}<small>Values use captured daily rates. Default settings apply only to future approvals.</small></section>`);
  }catch(error){if(!view||view.current())notify(error.message)}
}

