  const label=$('#schedule-week-label');if(label){if(scheduleView==='day')label.textContent=anchor.toLocaleDateString(locale,{weekday:'long',month:'long',day:'numeric',year:'numeric'});else if(scheduleView==='month')label.textContent=anchor.toLocaleDateString(locale,{month:'long',year:'numeric'});else label.textContent=`${sunday.toLocaleDateString(locale,{month:'long',day:'numeric',year:sunday.getFullYear()===saturday.getFullYear()?undefined:'numeric'})}–${saturday.toLocaleDateString(locale,{month:'long',day:'numeric',year:'numeric'})}`}
