function roundBudgetHours(value){return Math.round(Number(value)*100)/100}
function suggestedImportBudgetHours(quantity,targetHoursPerUnit){const qty=Number(quantity),rate=Number(targetHoursPerUnit);if(!Number.isFinite(qty)||qty<0||!Number.isFinite(rate)||rate<0)return 0;return roundBudgetHours(qty*rate)}
function applyImportCatalogMatch(line){if(line.budgetHoursUserEdited)return {...line};const matched=line.catalogItemId!=null&&line.catalogItemId!==''&&Number(line.catalogItemId);return {...line,budgetHours:matched?suggestedImportBudgetHours(line.quantity,line.targetHoursPerUnit):0,budgetHoursUserEdited:false}}
function typeImportBudgetHours(line,budgetHours){return {...line,budgetHours,budgetHoursUserEdited:true}}
function importHoursMissing(value){if(value==null||String(value).trim()==='')return true;const number=Number(value);return !Number.isFinite(number)||number<=0}
function importHoursWarningCount(lines){return (lines||[]).filter(line=>importHoursMissing(line.budgetHours)).length}
function importHoursSummaryText(count){const missing=Number(count)||0;if(!missing)return '';return `${missing} line${missing===1?' has':'s have'} no budget hours. You can still approve.`}
function importLineMarkup(line,index){const suggestions=(line.catalogSuggestions||[]).map(item=>`<option value="${item.id}" data-hours-per-unit="${escapeHtml(item.targetHoursPerUnit??'')}">${escapeHtml(item.name)} · ${escapeHtml(item.score)}%</option>`).join('');return `<div class="import-line-block"><div class="import-line"><input data-import-description="${index}" value="${escapeHtml(line.description)}"><input data-import-quantity="${index}" type="number" value="${escapeHtml(line.quantity)}"><input data-import-unit="${index}" value="${escapeHtml(line.unit)}"><input data-import-amount="${index}" type="number" value="${escapeHtml(line.amount||0)}"><select data-import-catalog="${index}"><option value="">No catalog match</option>${suggestions}</select><span class="status ${line.confidence==='high'?'':'warning'}">${escapeHtml(line.confidence)}</span></div><div class="import-line-hours"><label>Budget hours<input data-import-hours="${index}" type="number" min="0" step="0.01" value="0" data-user-edited="0" aria-label="Budget hours"></label><p class="import-hours-warning" data-import-hours-warning="${index}" role="status">This line has no budget hours.</p></div></div>`}
function refreshImportHoursWarning(index){const input=$(`[data-import-hours="${index}"]`),warning=$(`[data-import-hours-warning="${index}"]`);if(warning)warning.hidden=!importHoursMissing(input?input.value:'');refreshImportHoursSummary()}
function refreshImportHoursSummary(){const summary=$('#import-hours-summary');if(!summary)return;if(!estimateImportDraft?.lines?.length){summary.hidden=true;summary.textContent='';return}const count=importHoursWarningCount(estimateImportDraft.lines.map((_,index)=>{const input=$(`[data-import-hours="${index}"]`);return {budgetHours:input?input.value:''}}));const text=importHoursSummaryText(count);summary.hidden=!text;summary.textContent=text}
