reportDelayText=function(report){const facts=[report?.delays,report?.issue].map(value=>String(value||'').trim()),text=facts.find(value=>value&&!isNoDelayClaim(value)&&!/needs confirmation/i.test(value));if(text)return text;if(facts.some(isNoDelayClaim))return'No delays reported';return reportHasOpenUnplanned(report)?'Unplanned work needs a decision':'Not entered'};

function subcontractorCompliance(sub,now=new Date()){const required=[['Insurance',sub.insuranceExpiration],['Workers’ comp',sub.workersCompExpiration],['Contractor license',sub.licenseExpiration]],missing=[];let soonest=Infinity;for(const [name,value] of required){if(!value){missing.push(`${name} expiration`);continue}const days=Math.ceil((new Date(`${value}T23:59:59`)-now)/86400000);soonest=Math.min(soonest,days);if(days<0)missing.push(`${name} expired`)}if(!sub.w9Received)missing.push('W-9');if(!sub.agreementSigned)missing.push('Signed agreement');const warning=!missing.length&&soonest<=30;if(missing.length)return{key:'blocked',label:'Not cleared',detail:missing.join(' · '),missing,soonest};if(warning)return{key:'watch',label:'Expires soon',detail:`Next expiration in ${soonest} day${soonest===1?'':'s'}`,missing,soonest};return{key:'clear',label:'Cleared to work',detail:'Required information is current',missing,soonest}}
function complianceHistoryHtml(sub){const rows=(sub.complianceHistory||[]).slice().reverse();return rows.length?rows.map(row=>`<div class="compliance-history-entry"><span><strong>${escapeHtml(row.action||'Updated')}</strong><small>${escapeHtml(row.detail||'')}</small></span><small>${new Date(row.at).toLocaleString()}</small></div>`).join(''):'<p class="input-help">Updates and reminders will appear here.</p>'}
function openSubCompliance(id){const sub=subcontractors.find(item=>item.id===id);if(!sub)return;const status=subcontractorCompliance(sub);$('#sub-compliance-id').value=id;$('#sub-compliance-title').textContent=sub.name;$('#compliance-insurance').value=sub.insuranceExpiration||'';$('#compliance-workers-comp').value=sub.workersCompExpiration||'';$('#compliance-license-number').value=sub.licenseNumber||'';$('#compliance-license-expiration').value=sub.licenseExpiration||'';$('#compliance-w9').checked=Boolean(sub.w9Received);$('#compliance-agreement').checked=Boolean(sub.agreementSigned);$('#compliance-auto-reminders').checked=Boolean(sub.autoComplianceReminders);$('#compliance-notes').value=sub.notes||'';$('#sub-compliance-status').innerHTML=`<div class="compliance-status ${status.key}"><span><strong>${status.label}</strong><small>${escapeHtml(status.detail)}</small></span><b>${sub.autoComplianceReminders?'Automatic follow-up on':'Automatic follow-up off'}</b></div>`;$('#sub-compliance-history').innerHTML=complianceHistoryHtml(sub);$('#send-compliance-reminder').disabled=!sub.email;$('#sub-compliance-message').hidden=true;$('#sub-compliance-modal').showModal()}
const renderTeamDirectoryBeforeCompliance=renderTeamDirectory;
renderTeamDirectory=function(){const result=renderTeamDirectoryBeforeCompliance();if(teamTab!=='subcontractors')return result;$('#subcontractor-grid').innerHTML=subcontractors.length?subcontractors.map(sub=>{const links=subcontractorLinks.filter(link=>link.subcontractorId===sub.id),active=links.filter(link=>link.status==='Active'&&new Date(link.expiresAt)>new Date()).length,status=subcontractorCompliance(sub);return `<article class="panel subcontractor-card"><div class="sub-card-top"><span class="trade-badge">${escapeHtml(sub.trade||'Subcontractor')}</span><span class="status ${status.key==='blocked'?'danger':''}">${status.label}</span></div><h3>${escapeHtml(sub.name)}</h3><p>${escapeHtml(sub.contact||'No contact')} · <span class="exact-email">${escapeHtml(sub.email||'No email')}</span></p><div class="compliance-status ${status.key}"><span><strong>${status.label}</strong><small>${escapeHtml(status.detail)}</small></span></div><div class="sub-details"><small>INSURANCE <b>${sub.insuranceExpiration?formatDate(sub.insuranceExpiration):'Missing'}</b></small><small>LICENSE <b>${sub.licenseExpiration?formatDate(sub.licenseExpiration):'Missing'}</b></small><small>PROJECT LINKS <b>${active} active</b></small></div><div class="compliance-actions"><button class="project-open" data-sub-compliance="${sub.id}">Open compliance</button><button class="project-open" data-sub-link="${sub.id}">Project access</button></div></article>`}).join(''):'<div class="panel empty-directory">Add subcontractor companies here, then track whether each one is cleared to work.</div>';$$('[data-sub-compliance]').forEach(button=>button.onclick=()=>openSubCompliance(+button.dataset.subCompliance));$$('[data-sub-link]').forEach(button=>button.onclick=()=>openSubLink(+button.dataset.subLink));return result};
