function safetyItemMarkup(item={}){const status=['open','corrected','verified'].includes(item.status)?item.status:'open';return `<article class="safety-item"><button type="button" class="remove-safety-item" aria-label="Remove safety item">Remove</button><label>Observation or hazard<textarea data-safety-field="observation" rows="2" placeholder="What was observed and where">${escapeHtml(item.observation||'')}</textarea></label><label>Location<input data-safety-field="location" value="${escapeHtml(item.location||'')}" placeholder="West stair, level 2…"></label><label>Subcontractor / employer<input data-safety-field="company" value="${escapeHtml(item.company||'')}" placeholder="Company involved"></label><label>Person notified<input data-safety-field="notified" value="${escapeHtml(item.notified||'')}" placeholder="Name or competent person"></label><label>Immediate action<input data-safety-field="action" value="${escapeHtml(item.action||'')}" placeholder="Corrected, stopped, guarded…"></label><label>Responsible person<input data-safety-field="owner" value="${escapeHtml(item.owner||'')}" placeholder="Who owns follow-up"></label><label>Due date<input data-safety-field="dueDate" type="date" value="${escapeHtml(item.dueDate||'')}"></label><label>Status<select data-safety-field="status"><option value="open" ${status==='open'?'selected':''}>Open — follow-up needed</option><option value="corrected" ${status==='corrected'?'selected':''}>Corrected — verify</option><option value="verified" ${status==='verified'?'selected':''}>Verified closed</option></select></label><label>Verification<input data-safety-field="verification" value="${escapeHtml(item.verification||'')}" placeholder="Who verified and when"></label></article>`}
function renderSafetyItems(items=[]){const host=$('#safety-items');if(!host)return;host.innerHTML=(items||[]).map(safetyItemMarkup).join('');host.querySelectorAll('.remove-safety-item').forEach(button=>button.onclick=()=>button.closest('.safety-item').remove())}
function collectSafetyItems(){return [...$$('#safety-items .safety-item')].map(row=>Object.fromEntries([...row.querySelectorAll('[data-safety-field]')].map(input=>[input.dataset.safetyField,String(input.value||'').trim()]))).filter(item=>item.observation)}
function applyReportType(){const superintendent=$('#report-type')?.value==='superintendent',modal=$('#report-modal');modal?.classList.toggle('report-superintendent',superintendent);$('#superintendent-safety').hidden=!superintendent;const productionHeading=$('#production-rows')?.previousElementSibling;for(const node of [productionHeading,$('#hour-split-note'),$('#production-rows'),$('.labor-fieldset')])if(node)node.hidden=superintendent;$('#report-modal-title').textContent=editingReportId?(superintendent?'Verify superintendent log':'Verify daily report'):(superintendent?'Create superintendent log':'Create daily report');$('#ai-convert small').textContent=superintendent?'AI will organize site coordination, safety observations, subcontractor conversations, inspections, and next actions':'AI will propose production, labor, delays, materials, equipment, and safety details'}
