function renderDashboardDailyCount(){const today=companyTodayIso(),localTime=companyTime24(),activeProjectIds=new Set(workdays.filter(row=>row.status==='active').map(row=>row.projectId)),endedAssignmentProjects=new Set(assignments.filter(row=>row.date===today&&/^\d{2}:\d{2}$/.test(String(row.end||''))&&String(row.end)<=localTime&&!activeProjectIds.has(row.projectId)).map(row=>row.projectId)),submittedProjects=new Set(reports.filter(report=>report.status!=='Draft'&&report.dateIso===today).map(report=>projects[report.project]?.id).filter(Boolean)),expectedProjects=new Set([...endedAssignmentProjects,...submittedProjects]),submitted=[...submittedProjects].filter(id=>expectedProjects.has(id)).length,total=expectedProjects.size,card=$$('#dashboard-page .stat-card')[2];if(!card)return;card.querySelector('strong').innerHTML=`${submitted} <i>/ ${total}</i>`;const remaining=Math.max(0,total-submitted);card.querySelector('p').innerHTML=`<b class="amber-text">${remaining} ${remaining===1?'still due':'due'}</b>`}
