// Verified subcontractor tickets stay with the project and source daily.
const openProjectBeforeTickets=openProject;
function ticketLines(ticket){return ticket.lines?.length?ticket.lines:[{material:ticket.material||'',quantity:Number(ticket.quantity)||0,unit:ticket.unit||'',amount:Number(ticket.amount)||0}]}
function ticketStatusClass(status){return status==='Verified'?'clear':status==='Rejected'?'blocked':'watch'}
function ticketCsv(rows){const quote=pdlCsvCell,records=[['Project','Vendor','Ticket number','Date','Status','Material','Quantity','Unit']];for(const ticket of rows)for(const line of ticketLines(ticket))records.push([projects.find(project=>Number(project.id)===Number(ticket.projectId))?.name||'',ticket.vendor,ticket.ticketNumber,ticket.ticketDate,ticket.status||'Needs review',line.material,line.quantity,line.unit]);const blob=new Blob([records.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='project-tickets.csv';link.click();URL.revokeObjectURL(link.href)}
function ensureTicketModal(){if($('#project-ticket-modal'))return;document.body.insertAdjacentHTML('beforeend',`<dialog id="project-ticket-modal"><form method="dialog"><div class="modal-header"><div><p class="eyebrow">PROJECT TICKET</p><h2 id="ticket-modal-title">Review ticket</h2></div><button class="close-button" value="cancel">×</button></div><input id="ticket-edit-id" type="hidden"><div class="two-col"><label>Vendor<input id="ticket-edit-vendor"></label><label>Ticket number<input id="ticket-edit-number"></label></div><label>Ticket date<input id="ticket-edit-date" type="date"></label><label>Material lines<textarea id="ticket-edit-lines" rows="6" placeholder="Material | Quantity | Unit | Amount"></textarea><small class="input-help">One material per line. Use: Material | Quantity | Unit | Amount</small></label><label>Status<select id="ticket-edit-status"><option>Needs review</option><option>Verified</option><option>Rejected</option></select></label><div id="ticket-edit-history" class="compliance-history"></div><p id="ticket-edit-message" class="form-message" hidden></p><div class="modal-actions"><button type="button" class="secondary" id="ticket-delete">Delete with audit trail</button><button type="button" class="primary" id="ticket-save">Save ticket</button></div></form></dialog>`);$('#ticket-save').onclick=saveProjectTicket;$('#ticket-delete').onclick=deleteProjectTicket}
function openProjectTicket(id){ensureTicketModal();const ticket=projectTickets.find(row=>Number(row.id)===Number(id));if(!ticket)return;$('#ticket-edit-id').value=ticket.id;$('#ticket-modal-title').textContent=ticket.ticketNumber||`Ticket #${ticket.id}`;$('#ticket-edit-vendor').value=ticket.vendor||'';$('#ticket-edit-number').value=ticket.ticketNumber||'';$('#ticket-edit-date').value=ticket.ticketDate||'';$('#ticket-edit-lines').value=ticketLines(ticket).map(line=>[line.material,line.quantity,line.unit,line.amount||''].join(' | ')).join('\\n');$('#ticket-edit-status').value=ticket.status||'Needs review';$('#ticket-delete').hidden=!['owner','admin'].includes(currentUser?.role);$('#ticket-edit-history').innerHTML=(ticket.history||[]).slice().reverse().map(row=>`<div class="compliance-history-entry"><span><strong>${escapeHtml(row.action)}</strong><small>${escapeHtml(row.detail||'')}</small></span><small>${escapeHtml(row.by||'')} · ${new Date(row.at).toLocaleString()}</small></div>`).join('')||'<p class="input-help">No office changes yet.</p>';$('#ticket-edit-message').hidden=true;$('#project-ticket-modal').showModal()}
