async function deleteProjectTicket(){const id=+$('#ticket-edit-id').value,ticket=projectTickets.find(row=>row.id===id),reason=prompt('Why is this ticket being deleted? This reason is kept in the audit trail.');if(!reason)return;try{const result=await api(`/api/project-tickets/${id}`,{method:'DELETE',body:JSON.stringify({reason})});ticket.deletedAt=new Date().toISOString();ticket.status='Deleted';$('#project-ticket-modal').close();openProject(ticket.projectId);notify(`Ticket removed. Source file retained through ${new Date(result.retainedUntil).toLocaleDateString()} for recovery.`)}catch(error){notify(error.message)}}
