function resetEnhancedTemplateBuilder(){editingTemplateId=null;for(const id of ['template-name','template-description'])if($(id.startsWith('#')?id:`#${id}`))$(id.startsWith('#')?id:`#${id}`).value='';$('#template-category').value='daily';$('#template-require-photo').checked=false;$('#template-require-signature').checked=true;$('#template-require-ack').checked=false;$('#template-fields').innerHTML='';$('#template-safety-notice').hidden=true;$('#template-builder-title').textContent='Create a template';$('#template-draft-status').textContent='Not published';$('#template-save').textContent='Review & publish';$('#template-cancel').hidden=true}
