async function generateTemplateDraft(){const prompt=$('#template-ai-prompt').value.trim(),button=$('#template-ai-generate'),message=$('#template-ai-message');if(prompt.length<15){message.textContent='Describe who uses the form and what needs to be recorded.';message.hidden=false;return}button.disabled=true;button.textContent='Building draft…';message.hidden=true;try{const draft=await api('/api/daily-templates/generate',{method:'POST',body:JSON.stringify({prompt})});editingTemplateId=null;$('#template-name').value=draft.name||'';$('#template-category').value=draft.category||'daily';$('#template-description').value=draft.description||prompt;$('#template-require-photo').checked=draft.requirements?.photo===true;$('#template-require-signature').checked=draft.requirements?.signature!==false;$('#template-require-ack').checked=draft.requirements?.acknowledgement===true;$('#template-fields').innerHTML='';(draft.fields||[]).forEach(enhancedTemplateFieldRow);$('#template-safety-notice').hidden=draft.category!=='safety';$('#template-builder-title').textContent='Review AI draft';$('#template-draft-status').textContent='Draft—not published';$('#template-save').textContent='Review & publish';$('#template-cancel').hidden=false;message.textContent=draft.warning?`Starter draft created. ${draft.warning}`:'Draft created. Review every question before publishing.';message.hidden=false;$('#template-builder').scrollIntoView({behavior:'smooth',block:'start'})}catch(error){message.textContent=error.message;message.hidden=false}finally{button.disabled=false;button.textContent='✦ Build draft'}}
