document.addEventListener('click',async event=>{const edit=event.target.closest('[data-enhanced-template-edit]'),fallback=event.target.closest('[data-enhanced-template-default]'),remove=event.target.closest('[data-enhanced-template-delete]');if(!edit&&!fallback&&!remove)return;event.preventDefault();event.stopImmediatePropagation();try{if(edit)return loadEnhancedTemplateBuilder(templateById(edit.dataset.enhancedTemplateEdit));if(fallback){await api('/api/daily-templates/default',{method:'POST',body:JSON.stringify({templateId:fallback.dataset.enhancedTemplateDefault})});company.defaultTemplateId=fallback.dataset.enhancedTemplateDefault;renderEnhancedTemplateList();return notify('Company default template saved')}if(remove){if(!confirm('Delete this unused template? Completed forms and assigned templates are protected.'))return;await api(`/api/daily-templates/${encodeURIComponent(remove.dataset.enhancedTemplateDelete)}`,{method:'DELETE'});await refreshDailyTemplates();renderEnhancedTemplateList();notify('Template deleted')}}catch(error){notify(error.message)}},true);
