paintProjectTemplate=function(id){if(!templatesOn())return;const project=projects.find(item=>item.id===id),content=$('#project-detail-content');if(!project||!content||content.querySelector('#project-template-pin'))return;const selected=projectTemplateIds(project),office=['owner','admin'].includes(currentUser?.role);content.insertAdjacentHTML('afterbegin',`<section id="project-template-pin" class="templates-only project-form-library"><div><p class="eyebrow">PROJECT FORMS</p><h3>${office?'Assigned forms & safety checks':'Available field forms'}</h3><p>${office?'Choose every form this project may need. The first selection is the default daily.':'Open the correct form from My Day or a new daily report.'}</p></div><div class="project-template-options">${templateChoices().map(template=>`<label class="project-template-option"><input type="checkbox" data-project-template-choice="${escapeHtml(template.id)}" ${selected.includes(String(template.id))?'checked':''} ${office?'':'disabled'}><span><b>${escapeHtml(template.name)}</b><small>${templateCategoryLabel(template.category)} · ${escapeHtml(template.description||'Field form')}</small></span></label>`).join('')}</div>${office?'<button type="button" class="secondary" id="save-project-templates">Save project forms</button>':''}</section>`);if(office)$('#save-project-templates').onclick=async()=>{const templateIds=[...$$('[data-project-template-choice]:checked')].map(input=>input.dataset.projectTemplateChoice);if(!templateIds.length)return notify('Choose at least one project form');try{const updated=await api(`/api/projects/${id}/template`,{method:'PATCH',body:JSON.stringify({templateIds})});project.templateIds=updated.templateIds;project.templateId=updated.templateId;project.templateVersion=updated.templateVersion;notify('Project forms saved')}catch(error){notify(error.message)}}};

function enhancedCustomFieldsMarkup(template,version,values={}){return (version?.fields||[]).map(field=>{const value=values[field.id]??'',required=field.required?' data-custom-required="1"':'',label=`${escapeHtml(field.label)}${field.required?' *':''}`,help=field.help?`<small class="input-help">${escapeHtml(field.help)}</small>`:'';if(field.type==='checkbox')return `<label class="check-row template-ack"><input data-custom-field="${escapeHtml(field.id)}" data-custom-type="checkbox" data-custom-label="${escapeHtml(field.label)}" type="checkbox" ${value===true?'checked':''}${required}> <span>${label}${help}</span></label>`;if(field.type==='longtext')return `<label>${label}<textarea data-custom-field="${escapeHtml(field.id)}" data-custom-type="longtext" data-custom-label="${escapeHtml(field.label)}" rows="3"${required}>${escapeHtml(value)}</textarea>${help}</label>`;if(field.type==='number')return `<label>${label}<input data-custom-field="${escapeHtml(field.id)}" data-custom-type="number" data-custom-label="${escapeHtml(field.label)}" type="number" value="${escapeHtml(value)}"${required}>${help}</label>`;if(field.type==='date')return `<label>${label}<input data-custom-field="${escapeHtml(field.id)}" data-custom-type="date" data-custom-label="${escapeHtml(field.label)}" type="date" value="${escapeHtml(value)}"${required}>${help}</label>`;if(field.type==='yesno')return `<label>${label}<select data-custom-field="${escapeHtml(field.id)}" data-custom-type="yesno" data-custom-label="${escapeHtml(field.label)}"${required}><option value="">Select</option><option value="yes" ${value===true?'selected':''}>Yes</option><option value="no" ${value===false?'selected':''}>No</option></select>${help}</label>`;if(field.type==='dropdown')return `<label>${label}<select data-custom-field="${escapeHtml(field.id)}" data-custom-type="dropdown" data-custom-label="${escapeHtml(field.label)}"${required}><option value="">Select</option>${(field.options||[]).map(option=>`<option ${String(value)===String(option)?'selected':''}>${escapeHtml(option)}</option>`).join('')}</select>${help}</label>`;return `<label>${label}<input data-custom-field="${escapeHtml(field.id)}" data-custom-type="text" data-custom-label="${escapeHtml(field.label)}" value="${escapeHtml(value)}"${required}>${help}</label>`}).join('')}
const renderReportCustomFieldsBeforeMultiTemplate=renderReportCustomFields;
renderReportCustomFields=function(report){renderReportCustomFieldsBeforeMultiTemplate(report);if(!templatesOn()||report?.templateId)return;const project=projects[+$('#report-project').value],ids=projectTemplateIds(project),chosen=reportSelectedTemplateId&&ids.includes(String(reportSelectedTemplateId))?reportSelectedTemplateId:ids[0],template=templateById(chosen),version=templateVersionOf(template);if(!template||!version)return;const host=$('#report-custom-fields');host.dataset.templateId=template.id;host.dataset.templateVersion=String(version.version);host.dataset.legacy='0';host.innerHTML=`<div class="section-heading"><div><h3>${escapeHtml(template.name)}</h3><small>${templateCategoryLabel(template.category)} · version ${version.version}</small></div></div>${template.category==='safety'?'<div class="template-safety-notice"><strong>Complete and verify every safety answer</strong><p>This record supports your company program; it is not an automatic compliance certification.</p></div>':''}${enhancedCustomFieldsMarkup(template,version,{})}`};
const collectCustomFieldsBeforeCheckbox=collectCustomFields;
collectCustomFields=function(){const values=collectCustomFieldsBeforeCheckbox();$$('[data-custom-type="checkbox"]').forEach(field=>values[field.dataset.customField]=field.checked);return values};
function ensureReportTemplatePicker(report=null){let host=$('#report-template-picker');if(!host){host=document.createElement('label');host.id='report-template-picker';host.className='templates-only report-template-picker';host.innerHTML='Field form<select id="report-template-select"></select><small class="input-help">Choose the record you are completing. Required answers are checked before submission.</small>';$('#report-project-picker').insertAdjacentElement('afterend',host)}const project=projects[+$('#report-project').value],ids=projectTemplateIds(project),select=$('#report-template-select');select.innerHTML=ids.map(id=>{const template=templateById(id);return `<option value="${escapeHtml(id)}">${escapeHtml(template.name)} · ${templateCategoryLabel(template.category)}</option>`}).join('');reportSelectedTemplateId=report?.templateId||reportSelectedTemplateId&&ids.includes(String(reportSelectedTemplateId))?String(report?.templateId||reportSelectedTemplateId):ids[0];select.value=reportSelectedTemplateId;host.hidden=ids.length<2||Boolean(report);select.onchange=()=>{reportSelectedTemplateId=select.value;const template=templateById(select.value);if(template.category==='safety'&&$('#report-type')){$('#report-type').value='superintendent';applyReportType()}renderReportCustomFields(null);rememberActiveReport()}}
const openReportBeforeMultipleTemplates=openReport;
openReport=function(report=null){reportSelectedTemplateId=report?.templateId||null;const result=openReportBeforeMultipleTemplates(report);ensureReportTemplatePicker(report);renderReportCustomFields(report);return result};
const renderReportJobContextBeforeMultipleTemplates=renderReportJobContext;
renderReportJobContext=function(options={}){const result=renderReportJobContextBeforeMultipleTemplates(options);if($('#report-modal')?.open&&!editingReportId){ensureReportTemplatePicker();renderReportCustomFields(null)}return result};
const saveDailyReportBeforeTemplateRequirements=saveDailyReport;
saveDailyReport=async function(status){if(status!=='Draft'&&templatesOn()){const template=templateById($('#report-custom-fields')?.dataset.templateId),requirements=template?.requirements||{},existingPhoto=editingReportId&&photos.some(photo=>Number(photo.reportId)===Number(editingReportId));if(requirements.photo&&!$('#report-photos')?.files?.length&&!existingPhoto){showReportMessage(`${template.name} requires at least one photo.`);showReportStep(1);return}if(requirements.signature&&!$('#report-signature')?.value.trim()){showReportMessage(`${template.name} requires the foreman signature.`);return}const unchecked=[...$$('[data-custom-required][data-custom-type="checkbox"]')].find(field=>!field.checked);if(unchecked){showReportMessage(`${unchecked.dataset.customLabel||'Acknowledgement'} must be confirmed.`);return}}return saveDailyReportBeforeTemplateRequirements(status)};
const renderMyDayBeforeRequiredForms=renderMyDay;
renderMyDay=function(){const result=renderMyDayBeforeRequiredForms(),memberId=currentUser?.memberId,today=companyTodayIso(),todayItems=assignments.filter(item=>item.date===today&&(!memberId||(item.memberIds||[]).map(Number).includes(Number(memberId)))),cards=$$('#field-today .field-assignment-card');todayItems.forEach((assignment,index)=>{const project=projects.find(row=>Number(row.id)===Number(assignment.projectId)),forms=projectTemplateIds(project).map(templateById).filter(template=>template&&(template.category||'daily')!=='daily');if(!forms.length||!cards[index])return;cards[index].insertAdjacentHTML('beforeend',`<div class="assignment-required-forms"><small>PROJECT FORMS</small>${forms.map(template=>{const completed=reports.some(report=>String(report.templateId)===String(template.id)&&reportWorkDate(report)===today&&Number(fieldProjectForReport(report)?.id)===Number(project?.id)&&report.status!=='Draft');return `<button type="button" class="secondary small" data-assignment-form="${assignment.id}" data-template-id="${escapeHtml(template.id)}" ${completed?'disabled':''}>${completed?'✓ Completed':`${template.category==='safety'?'⚠ ':''}${escapeHtml(template.name)}`}</button>`}).join('')}</div>`)});$$('[data-assignment-form]').forEach(button=>button.onclick=()=>{const assignment=assignments.find(row=>Number(row.id)===Number(button.dataset.assignmentForm));reportSelectedTemplateId=button.dataset.templateId;if(assignment)openDailyForAssignment(assignment);reportSelectedTemplateId=button.dataset.templateId;ensureReportTemplatePicker();$('#report-template-select').value=button.dataset.templateId;renderReportCustomFields(null)});return result};

// Photo-required templates use a two-phase transaction: save a protected draft,
// upload the linked photo, then submit. A failed upload leaves a recoverable draft.
let pendingTemplatePhotoSubmission=null;
const apiBeforeTemplatePhotoTransaction=api;
api=async function(url,options={}){const reportRoute=String(url)==='/api/reports'||/^\/api\/reports\/\d+$/.test(String(url));if(reportRoute&&['POST','PATCH'].includes(options.method)){let payload;try{payload=JSON.parse(options.body||'{}')}catch{}const template=payload&&templateById(payload.templateId||$('#report-custom-fields')?.dataset.templateId),existingPhoto=editingReportId&&photos.some(photo=>Number(photo.reportId)===Number(editingReportId)),newPhoto=$('#report-photos')?.files?.length>0;if(payload&&payload.status&&payload.status!=='Draft'&&template?.requirements?.photo&&newPhoto&&!existingPhoto){const requestedStatus=payload.status,draft=await apiBeforeTemplatePhotoTransaction(url,{...options,body:JSON.stringify({...payload,status:'Draft'})});pendingTemplatePhotoSubmission={report:draft,payload:{...payload,status:requestedStatus}};return draft}}return apiBeforeTemplatePhotoTransaction(url,options)};
const uploadPhotosBeforeTemplateTransaction=uploadPhotos;
uploadPhotos=async function(context){const uploaded=await uploadPhotosBeforeTemplateTransaction(context),pending=pendingTemplatePhotoSubmission;if(pending&&Number(context.reportId)===Number(pending.report.id)){pendingTemplatePhotoSubmission=null;const submitted=await apiBeforeTemplatePhotoTransaction(`/api/reports/${pending.report.id}`,{method:'PATCH',body:JSON.stringify(pending.payload)});Object.assign(pending.report,submitted)}return uploaded};

// Focused Projects-page quality pass: clear counts, honest filters, and
// consistent card language on desktop and phones.
const renderProjectCardsBeforeFocusedPolish=renderProjectCards;
renderProjectCards=function(filter=''){
  const result=renderProjectCardsBeforeFocusedPolish(filter),normalized=String(filter||'').trim().toLowerCase(),status=$('#project-status-filter')?.value||'all',base=projects.filter(project=>Boolean(project.archived)===(projectView==='archived')),visible=base.filter(project=>(status==='all'||projectHealth(project)===status)&&`${project.name} ${project.customer} ${project.site||''}`.toLowerCase().includes(normalized)),spanish=preferredLanguage==='es';
  $$('[data-project-view]').forEach(button=>{button.querySelector('.project-view-count')?.remove();const count=projects.filter(project=>Boolean(project.archived)===(button.dataset.projectView==='archived')).length;button.insertAdjacentHTML('beforeend',` <span class="project-view-count">${count}</span>`)});
  const summary=$('#project-results-summary');if(summary)summary.textContent=spanish?`${visible.length} de ${base.length} proyecto${base.length===1?'':'s'}`:`Showing ${visible.length} of ${base.length} ${projectView} project${base.length===1?'':'s'}`;
  $$('#project-cards .project-card[data-project-card]').forEach(card=>{const project=projects.find(row=>Number(row.id)===Number(card.dataset.projectCard)),health=project&&projectHealth(project),progressLabel=card.querySelector('.progress-label span'),open=card.querySelector('.project-open');if(progressLabel)progressLabel.textContent=spanish?'Avance aprobado':'Approved completion';if(open)open.textContent=spanish?'Ver detalles del proyecto →':'View project details →';if(project)card.setAttribute('aria-label',`${spanish?'Abrir':'Open'} ${project.name}. ${health}. ${Number(project.progress||0)}% ${spanish?'completo':'complete'}.`)});
  if(base.length&&!visible.length){$('#project-cards').innerHTML=`<div class="empty-state project-filter-empty"><strong>${spanish?'Ningún proyecto coincide':'No projects match these filters'}</strong><p>${spanish?'Borra la búsqueda o muestra todos los estados.':'Clear the search or show every project status.'}</p><button type="button" class="secondary" id="clear-project-filters">${spanish?'Borrar filtros':'Clear filters'}</button></div>`;$('#clear-project-filters').onclick=()=>{$('#project-search').value='';$('#project-status-filter').value='all';renderProjectCards('')}}
  return result;
};
